// Display helpers shared by the invoice web page and the PDF, so both always
// show numbers the same way.

export function formatQuantity(hundredths: number): string {
  return (hundredths / 100).toLocaleString("en-US", {
    maximumFractionDigits: 2,
  });
}

export function formatTaxRate(bps: number): string {
  return `${(bps / 100).toLocaleString("en-US", { maximumFractionDigits: 2 })}%`;
}

export function formatStatus(status: string): string {
  return status.charAt(0) + status.slice(1).toLowerCase();
}

// INV-0001 → "INV-0001.pdf". Invoice numbers are generated by the app, but
// strip anything unexpected so the header can't be broken by odd input.
export function pdfFilename(invoiceNumber: string): string {
  return `${invoiceNumber.replace(/[^A-Za-z0-9-]/g, "") || "invoice"}.pdf`;
}
